#include <algorithm>
#include <chrono>
#include <iostream>
#include <limits>
#include <mutex>
#include <stdexcept>
#include <thread>
#include <utility>
#include <vector>
#include "sched/pool.hpp"

using mhgp10::u64;
using Interval = std::pair<u64, u64>;
struct Case { const char* name; u64 n, grain; std::vector<Interval> expected; };

int main() {
  const u64 top = std::numeric_limits<u64>::max();
  const u64 half = u64(1) << 63;
  const Case cases[] = {
      {"small_n_huge_grain", 17, half, {{0, 17}}},
      {"max_n_one_chunk", top, top, {{0, top}}},
      {"max_n_remainder_one", top, top - 1, {{0, top - 1}, {top - 1, top}}},
      {"max_n_half_chunks", top, half, {{0, half}, {half, top}}},
  };
  bool all = true;
  for (unsigned threads : {1u, 4u}) {
    mhgp10::sched::Pool pool(threads);
    for (const auto& c : cases) {
      std::mutex mutex;
      std::vector<Interval> actual;
      pool.parallel_for(c.n, c.grain, [&](u64 begin, u64 end, unsigned) {
        {
          std::lock_guard<std::mutex> lock(mutex);
          actual.emplace_back(begin, end);
          if (actual.size() > 4 || !(begin < end && end <= c.n)) throw std::runtime_error("bad interval");
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(2));
      });
      std::sort(actual.begin(), actual.end());
      const bool ok = actual == c.expected && !mhgp10::sched::in_parallel_region();
      all = all && ok;
      std::cout << c.name << " threads=" << threads << " chunks=" << actual.size() << " ok=" << ok << '\n';
    }
  }
  {
    mhgp10::sched::Pool pool(4);
    std::vector<Interval> actual;
    pool.parallel_for(1, 1, [&](u64, u64, unsigned) {
      pool.parallel_for(top, half, [&](u64 begin, u64 end, unsigned) { actual.emplace_back(begin, end); });
    });
    const bool ok = actual == cases[3].expected && pool.nested_calls() == 1 && !mhgp10::sched::in_parallel_region();
    all = all && ok;
    std::cout << "nested_max_n_half_chunks chunks=" << actual.size() << " ok=" << ok << '\n';
  }
  return all ? 0 : 1;
}

